using System;
using System.Collections.Generic;
using ResolverMaster.Core.Puzzle;
using UnityEngine;

namespace ResolverMaster.Core.UI.Themes
{
    /// <summary>
    /// Art of the chapter themes generated by code from the <see cref="VisualTheme"/> colors and seed (same theme = same pictures on
    /// every phone): the cell slab (4 variants), the seamless ground drawn between the cells (Image.Type.Tiled) and the screen backdrop.
    /// A theme image set in the parameters (Gemini, later) is returned instead of the generated one.
    /// Generated once per theme and kept for the whole run (textures are not saved in the project).
    /// </summary>
    public static class ThemeArt
    {
        /// <summary>Side of a generated cell slab (px): at least the biggest cell of the game screen, so it is never scaled up.</summary>
        public const int SlabSize = 336;
        public const int SlabVariants = 4;
        public const int GroundSize = 256;
        /// <summary>The backdrop is drawn at half the 9:21 screen and anchored to the bottom (soft art: 2x is fine).</summary>
        public const int BackdropWidth = 540, BackdropHeight = 1260;

        static readonly Dictionary<string, Sprite> s_cache = new Dictionary<string, Sprite>();

        public static Sprite Slab(VisualTheme t, int variant)
        {
            if (t.slabImage != null) return t.slabImage;
            variant = ((variant % SlabVariants) + SlabVariants) % SlabVariants;
            return Cached(t, "slab" + variant, () => MakeSlab(t, variant));
        }

        public static Sprite Ground(VisualTheme t) => t.groundImage != null ? t.groundImage : Cached(t, "ground", () => MakeGround(t));

        public static Sprite Backdrop(VisualTheme t) => t.backdropImage != null ? t.backdropImage : Cached(t, "backdrop", () => MakeBackdrop(t));

        static Sprite Cached(VisualTheme t, string what, Func<Sprite> make)
        {
            string key = $"{t.id}|{what}|{t.seed}|{t.terrain}|{t.backdrop}|{t.ground}|{t.groundDetail}|{t.slab}|{t.slabDetail}|{t.slabEdge}|" +
                         $"{t.skyTop}|{t.skyBottom}|{t.landA}|{t.landB}|{t.landDetail}";
            if (s_cache.TryGetValue(key, out var s) && s != null && s.texture != null) return s;
            s = make();
            s_cache[key] = s;
            return s;
        }

        // ------------------------------------------------------------------ cell slab

        static Sprite MakeSlab(VisualTheme t, int variant)
        {
            int n = SlabSize;
            var c = new Raster(n, n, wrap: false);
            var rng = new SeededRandom(t.seed * 31 + variant * 7 + 1);
            float margin = n * 0.035f, radius = n * 0.13f, rim = n * 0.07f;
            int nseed = t.seed * 13 + variant;
            // body with a soft texture, darker rim towards the edge
            for (int y = 0; y < n; y++)
            for (int x = 0; x < n; x++)
            {
                float d = RoundBox(x + 0.5f, y + 0.5f, margin, margin, n - margin, n - margin, radius);
                float a = Mathf.Clamp01(0.5f - d);
                if (a <= 0f) continue;
                float tex = 0.94f + 0.10f * Noise.Fbm(x / 46f, y / 46f, nseed);
                var body = t.slab * tex;
                var col = Color.Lerp(t.slabEdge, body, Smooth(0f, rim, -d));
                col = Color.Lerp(t.slabEdge * 0.62f, col, Mathf.Clamp01(-d - 2.2f));   // thin darker border line
                col.a = a;
                c.Set(x, y, col);
            }
            // details inside the slab (kept away from the rim)
            float lo = margin + rim * 1.1f, hi = n - margin - rim * 1.1f;
            switch (t.terrain)
            {
                case TerrainPattern.Grass:
                    for (int i = 0; i < 46; i++) c.Disk(R(rng, lo, hi), R(rng, lo, hi), R(rng, 1.2f, 2.8f), t.slabDetail, 0.75f);
                    for (int k = 0; k < 2; k++)
                    {
                        // a small crack: a few joined thin segments
                        float x = R(rng, lo, hi), y = R(rng, lo, hi), ang = R(rng, 0f, 6.28f);
                        for (int s = 0; s < 4; s++)
                        {
                            ang += R(rng, -0.8f, 0.8f);
                            float len = R(rng, 10f, 20f);
                            float nx = Mathf.Clamp(x + Mathf.Cos(ang) * len, lo, hi), ny = Mathf.Clamp(y + Mathf.Sin(ang) * len, lo, hi);
                            c.Line(x, y, nx, ny, 1.6f, t.slabEdge * 0.85f, 0.7f);
                            x = nx;
                            y = ny;
                        }
                    }
                    // a little moss tuft in one corner
                    Tuft(c, rng, margin + rim * 0.9f + R(rng, 0f, 8f), margin + rim * 0.9f + R(rng, 0f, 8f), t.groundDetail, 9f, 0.9f);
                    break;
                case TerrainPattern.Dirt:
                    for (int i = 0; i < 22; i++)
                    {
                        float x = R(rng, lo, hi), y = R(rng, lo, hi), ang = R(rng, 0f, 3.14f), len = R(rng, 12f, 26f);
                        c.Line(x, y, x + Mathf.Cos(ang) * len, y + Mathf.Sin(ang) * len, 2.0f, t.slabDetail, 0.85f);
                    }
                    for (int i = 0; i < 16; i++) c.Disk(R(rng, lo, hi), R(rng, lo, hi), R(rng, 1.5f, 3f), t.slabEdge, 0.6f);
                    break;
                default:
                    for (int i = 0; i < 120; i++) c.Disk(R(rng, lo, hi), R(rng, lo, hi), R(rng, 0.8f, 1.6f), rng.Chance(0.5) ? t.slabDetail : t.slab * 1.06f, 0.7f);
                    // bevel: a light line inside the top-left of the slab
                    c.Line(margin + rim, n - margin - rim, n - margin - rim, n - margin - rim, 2f, Color.white, 0.35f);
                    c.Line(margin + rim, margin + rim, margin + rim, n - margin - rim, 2f, Color.white, 0.35f);
                    break;
            }
            return c.ToSprite($"theme_{t.id}_slab{variant}", TextureWrapMode.Clamp, mipmaps: true);
        }

        // ------------------------------------------------------------------ ground between the cells (seamless)

        static Sprite MakeGround(VisualTheme t)
        {
            int n = GroundSize;
            var c = new Raster(n, n, wrap: true);
            var rng = new SeededRandom(t.seed * 17 + 5);
            int nseed = t.seed * 7;
            for (int y = 0; y < n; y++)
            for (int x = 0; x < n; x++)
            {
                float tex = 0.92f + 0.14f * Noise.FbmPeriodic(x / 32f, y / 32f, n / 32, nseed);
                var col = t.ground * tex;
                col.a = 1f;
                c.Set(x, y, col);
            }
            switch (t.terrain)
            {
                case TerrainPattern.Grass:
                    for (int i = 0; i < 60; i++) Tuft(c, rng, R(rng, 0, n), R(rng, 0, n), rng.Chance(0.6) ? t.groundDetail : t.ground * 1.18f, R(rng, 8f, 14f), 0.95f);
                    for (int i = 0; i < 30; i++) c.Disk(R(rng, 0, n), R(rng, 0, n), R(rng, 1.2f, 2.2f), t.ground * 1.25f, 0.8f);
                    break;
                case TerrainPattern.Dirt:
                    for (int i = 0; i < 55; i++)
                    {
                        float x = R(rng, 0, n), y = R(rng, 0, n), ang = R(rng, 0f, 3.14f), len = R(rng, 9f, 20f);
                        c.Line(x, y, x + Mathf.Cos(ang) * len, y + Mathf.Sin(ang) * len, 1.7f, t.groundDetail, 0.9f);
                    }
                    for (int i = 0; i < 26; i++) c.Disk(R(rng, 0, n), R(rng, 0, n), R(rng, 1.8f, 3.4f), t.ground * 0.78f, 0.8f);
                    break;
                default:
                    for (int i = 0; i < 260; i++) c.Disk(R(rng, 0, n), R(rng, 0, n), R(rng, 0.7f, 1.4f), rng.Chance(0.5) ? t.groundDetail : t.ground * 1.12f, 0.8f);
                    break;
            }
            return c.ToSprite($"theme_{t.id}_ground", TextureWrapMode.Repeat, mipmaps: false);
        }

        // ------------------------------------------------------------------ screen backdrop

        static Sprite MakeBackdrop(VisualTheme t)
        {
            int w = BackdropWidth, h = BackdropHeight;
            var c = new Raster(w, h, wrap: false);
            var rng = new SeededRandom(t.seed * 23 + 11);
            int nseed = t.seed * 3 + 1;
            switch (t.backdrop)
            {
                case BackdropPattern.Meadow:
                {
                    float horizon = 0.70f;
                    Fill(c, nseed, 50f, (u, v) =>
                    {
                        float far = horizon + 0.035f * Mathf.Sin(u * 5.1f + 0.7f) + 0.02f * Mathf.Sin(u * 11.3f);
                        float near = horizon - 0.045f + 0.03f * Mathf.Sin(u * 3.3f + 2.1f);
                        if (v > far) return (Color.Lerp(t.skyBottom, t.skyTop, Smooth(far, 1f, v)), false);
                        if (v > near) return (Color.Lerp(t.landA, t.skyBottom, 0.35f), true);
                        return (Color.Lerp(t.landB, t.landA, Mathf.Pow(v / near, 1.4f)), true);
                    });
                    for (int i = 0; i < 5; i++) Cloud(c, rng, R(rng, 0, w), h * R(rng, horizon + 0.08f, 0.96f), R(rng, 26f, 44f), Color.white);
                    for (int i = 0; i < 170; i++) Tuft(c, rng, R(rng, 0, w), h * R(rng, 0.02f, horizon - 0.08f), t.landB * 0.85f, R(rng, 7f, 12f), 0.85f);
                    Color[] flowers = { t.landDetail, UiKitStyle.Hex(0xFFC6D9), UiKitStyle.Hex(0xFFE680), Color.white };
                    for (int i = 0; i < 150; i++)
                    {
                        float x = R(rng, 0, w), y = h * R(rng, 0.02f, horizon - 0.07f), r = R(rng, 2f, 3.6f);
                        c.Disk(x, y, r, flowers[rng.Next(flowers.Length)], 1f);
                        c.Disk(x, y, r * 0.38f, UiKitStyle.Hex(0xF2C230), 1f);
                    }
                    break;
                }
                case BackdropPattern.Fields:
                {
                    float horizon = 0.74f;
                    const int bands = 9;
                    Fill(c, nseed, 40f, (u, v) =>
                    {
                        float hz = horizon + 0.015f * Mathf.Sin(u * 4.2f);
                        if (v > hz) return (Color.Lerp(t.skyBottom, t.skyTop, Smooth(hz, 1f, v)), false);
                        // stripes get thicker towards the bottom (perspective) and wave a little
                        float k = Mathf.Pow(1f - v / hz, 0.62f) * bands + 0.25f * Mathf.Sin(u * 6.3f + v * 9f);
                        int band = Mathf.FloorToInt(k);
                        float f = k - band;
                        var col = band % 2 == 0 ? t.landA : t.landB;
                        if (band % 3 == 2) col = Color.Lerp(t.landA, t.landB, 0.5f);
                        // furrows inside the brown stripes
                        if (band % 2 == 1 && Mathf.Abs(Mathf.Sin(f * Mathf.PI * 5f)) > 0.9f) col *= 0.88f;
                        return (col, true);
                    });
                    for (int i = 0; i < 4; i++) Cloud(c, rng, R(rng, 0, w), h * R(rng, horizon + 0.08f, 0.96f), R(rng, 24f, 40f), Color.white);
                    for (int i = 0; i < 90; i++)
                    {
                        float x = R(rng, 0, w), y = h * R(rng, 0.02f, horizon - 0.05f), ang = R(rng, 0f, 3.14f), len = R(rng, 6f, 12f);
                        c.Line(x, y, x + Mathf.Cos(ang) * len, y + Mathf.Sin(ang) * len, 1.6f, t.landDetail, 0.55f);
                    }
                    break;
                }
                default:
                {
                    float street = 0.46f;
                    Fill(c, nseed, 40f, (u, v) => v > street ? (Color.Lerp(t.skyBottom, t.skyTop, Smooth(street, 1f, v)), false) : (t.landB, true));
                    // pavement joints
                    for (float y = 24; y < h * street; y += 46) c.Line(0, y, w, y, 1.5f, t.landB * 0.86f, 0.6f);
                    // two rows of simple buildings: the far one lighter
                    Buildings(c, rng, h * (street + 0.06f), Color.Lerp(t.landA, t.skyBottom, 0.45f), 0.10f, 0.26f, null);
                    Buildings(c, rng, h * street, t.landA, 0.06f, 0.20f, t.landDetail);
                    break;
                }
            }
            return c.ToSprite($"theme_{t.id}_backdrop", TextureWrapMode.Clamp, mipmaps: false);
        }

        /// <summary>
        /// Fills the backdrop from a shape function of (u, v) in 0..1 (v up): 2x2 samples per pixel (smooth edges between hills, fields
        /// and sky); the land gets a soft noise texture (computed once per pixel).
        /// </summary>
        static void Fill(Raster c, int nseed, float noiseScale, Func<float, float, (Color color, bool land)> shape)
        {
            int w = c.Width, h = c.Height;
            for (int y = 0; y < h; y++)
            for (int x = 0; x < w; x++)
            {
                float n = 0.95f + 0.08f * Noise.Fbm(x / noiseScale, y / noiseScale, nseed);
                var sum = new Color(0, 0, 0, 0);
                for (int sy = 0; sy < 2; sy++)
                for (int sx = 0; sx < 2; sx++)
                {
                    var (col, land) = shape((x + 0.25f + 0.5f * sx) / w, (y + 0.25f + 0.5f * sy) / h);
                    sum += land ? col * n : col;
                }
                sum *= 0.25f;
                sum.a = 1f;
                c.Set(x, y, sum);
            }
        }

        static void Buildings(Raster c, SeededRandom rng, float baseY, Color color, float minH, float maxH, Color? windows)
        {
            float x = -R(rng, 0f, 40f);
            while (x < c.Width)
            {
                float bw = R(rng, 44f, 96f), bh = c.Height * R(rng, minH, maxH);
                c.Rect(x, baseY, x + bw, baseY + bh, color, 1f);
                c.Rect(x, baseY + bh - 6f, x + bw, baseY + bh, color * 0.9f, 1f);   // roof line
                if (windows.HasValue)
                    for (float wy = baseY + 22f; wy < baseY + bh - 26f; wy += 30f)
                    for (float wx = x + 10f; wx < x + bw - 18f; wx += 22f)
                        if (rng.Chance(0.75)) c.Rect(wx, wy, wx + 10f, wy + 14f, windows.Value, 0.55f);
                x += bw + R(rng, 4f, 18f);
            }
        }

        static void Tuft(Raster c, SeededRandom rng, float x, float y, Color color, float len, float alpha)
        {
            for (int b = -1; b <= 1; b++)
            {
                float ang = Mathf.PI / 2f + b * 0.45f + R(rng, -0.15f, 0.15f);
                float l = len * (b == 0 ? 1f : 0.75f);
                c.Line(x, y, x + Mathf.Cos(ang) * l, y + Mathf.Sin(ang) * l, 2.1f, color, alpha);
            }
        }

        static void Cloud(Raster c, SeededRandom rng, float x, float y, float r, Color color)
        {
            c.Disk(x, y, r, color, 0.75f);
            c.Disk(x - r * 0.9f, y - r * 0.25f, r * 0.7f, color, 0.75f);
            c.Disk(x + r * 0.95f, y - r * 0.2f, r * 0.75f, color, 0.75f);
        }

        static float R(SeededRandom rng, float a, float b) => a + (float)rng.NextDouble() * (b - a);

        static float Smooth(float a, float b, float x)
        {
            float t = Mathf.Clamp01((x - a) / Mathf.Max(1e-5f, b - a));
            return t * t * (3f - 2f * t);
        }

        /// <summary>Signed distance to a rounded box in px (negative inside).</summary>
        static float RoundBox(float px, float py, float x0, float y0, float x1, float y1, float r)
        {
            float cx = (x0 + x1) / 2f, cy = (y0 + y1) / 2f;
            float qx = Mathf.Abs(px - cx) - ((x1 - x0) / 2f - r);
            float qy = Mathf.Abs(py - cy) - ((y1 - y0) / 2f - r);
            return new Vector2(Mathf.Max(qx, 0), Mathf.Max(qy, 0)).magnitude + Mathf.Min(Mathf.Max(qx, qy), 0) - r;
        }

        /// <summary>A small software canvas (straight alpha, origin bottom-left) with anti-aliased disks, lines and rectangles.</summary>
        sealed class Raster
        {
            public readonly int Width, Height;
            readonly Color[] _px;
            readonly bool _wrap;

            public Raster(int w, int h, bool wrap)
            {
                Width = w;
                Height = h;
                _wrap = wrap;
                _px = new Color[w * h];
            }

            public void Set(int x, int y, Color c) => _px[y * Width + x] = c;

            void Blend(int x, int y, Color c, float a)
            {
                if (_wrap)
                {
                    x = ((x % Width) + Width) % Width;
                    y = ((y % Height) + Height) % Height;
                }
                else if (x < 0 || y < 0 || x >= Width || y >= Height) return;
                int i = y * Width + x;
                var d = _px[i];
                if (d.a <= 0f) return;   // never paint outside the shape (slab corners stay transparent)
                float k = Mathf.Clamp01(a);
                _px[i] = new Color(d.r + (c.r - d.r) * k, d.g + (c.g - d.g) * k, d.b + (c.b - d.b) * k, d.a);
            }

            public void Disk(float cx, float cy, float r, Color c, float alpha)
            {
                for (int y = Mathf.FloorToInt(cy - r - 1); y <= Mathf.CeilToInt(cy + r + 1); y++)
                for (int x = Mathf.FloorToInt(cx - r - 1); x <= Mathf.CeilToInt(cx + r + 1); x++)
                {
                    float d = Mathf.Sqrt((x + 0.5f - cx) * (x + 0.5f - cx) + (y + 0.5f - cy) * (y + 0.5f - cy)) - r;
                    float a = Mathf.Clamp01(0.5f - d);
                    if (a > 0f) Blend(x, y, c, a * alpha);
                }
            }

            public void Line(float x0, float y0, float x1, float y1, float width, Color c, float alpha)
            {
                float hw = width / 2f;
                var a0 = new Vector2(x0, y0);
                var ba = new Vector2(x1 - x0, y1 - y0);
                float len2 = Mathf.Max(1e-5f, ba.sqrMagnitude);
                for (int y = Mathf.FloorToInt(Mathf.Min(y0, y1) - hw - 1); y <= Mathf.CeilToInt(Mathf.Max(y0, y1) + hw + 1); y++)
                for (int x = Mathf.FloorToInt(Mathf.Min(x0, x1) - hw - 1); x <= Mathf.CeilToInt(Mathf.Max(x0, x1) + hw + 1); x++)
                {
                    var pa = new Vector2(x + 0.5f, y + 0.5f) - a0;
                    float h = Mathf.Clamp01(Vector2.Dot(pa, ba) / len2);
                    float d = (pa - ba * h).magnitude - hw;
                    float a = Mathf.Clamp01(0.5f - d);
                    if (a > 0f) Blend(x, y, c, a * alpha);
                }
            }

            public void Rect(float x0, float y0, float x1, float y1, Color c, float alpha)
            {
                for (int y = Mathf.FloorToInt(y0); y < Mathf.CeilToInt(y1); y++)
                for (int x = Mathf.FloorToInt(x0); x < Mathf.CeilToInt(x1); x++)
                {
                    float cover = Mathf.Clamp01(Mathf.Min(x + 1, x1) - Mathf.Max(x, x0)) * Mathf.Clamp01(Mathf.Min(y + 1, y1) - Mathf.Max(y, y0));
                    if (cover > 0f) Blend(x, y, c, cover * alpha);
                }
            }

            public Sprite ToSprite(string name, TextureWrapMode wrapMode, bool mipmaps)
            {
                var tex = new Texture2D(Width, Height, TextureFormat.RGBA32, mipmaps)
                {
                    name = name,
                    wrapMode = wrapMode,
                    filterMode = mipmaps ? FilterMode.Trilinear : FilterMode.Bilinear,
                    hideFlags = HideFlags.HideAndDontSave,
                };
                var px = new Color32[_px.Length];
                for (int i = 0; i < px.Length; i++) px[i] = _px[i];
                tex.SetPixels32(px);
                tex.Apply(mipmaps, true);
                var sprite = Sprite.Create(tex, new Rect(0, 0, Width, Height), new Vector2(0.5f, 0.5f), 100f, 0, SpriteMeshType.FullRect);
                sprite.name = name;
                sprite.hideFlags = HideFlags.HideAndDontSave;
                return sprite;
            }
        }

        /// <summary>Value noise (deterministic integer hash, same on every platform), plain and periodic (seamless tiles).</summary>
        static class Noise
        {
            static float Hash(int x, int y, int seed)
            {
                unchecked
                {
                    uint h = (uint)(x * 374761393 + y * 668265263 + seed * 2147483647);
                    h = (h ^ (h >> 13)) * 1274126177u;
                    h ^= h >> 16;
                    return (h & 0xFFFFFF) / 16777215f;
                }
            }

            static float Value(float x, float y, int seed, int period)
            {
                int x0 = Mathf.FloorToInt(x), y0 = Mathf.FloorToInt(y);
                float fx = x - x0, fy = y - y0;
                fx = fx * fx * (3 - 2 * fx);
                fy = fy * fy * (3 - 2 * fy);
                int Wrap(int v) => period > 0 ? ((v % period) + period) % period : v;
                float a = Hash(Wrap(x0), Wrap(y0), seed), b = Hash(Wrap(x0 + 1), Wrap(y0), seed);
                float c = Hash(Wrap(x0), Wrap(y0 + 1), seed), d = Hash(Wrap(x0 + 1), Wrap(y0 + 1), seed);
                return Mathf.Lerp(Mathf.Lerp(a, b, fx), Mathf.Lerp(c, d, fx), fy);
            }

            public static float Fbm(float x, float y, int seed) => 0.6f * Value(x, y, seed, 0) + 0.4f * Value(x * 2.3f, y * 2.3f, seed + 7, 0);

            /// <summary>Repeats every <paramref name="period"/> units (tiles without seams).</summary>
            public static float FbmPeriodic(float x, float y, int period, int seed) =>
                0.6f * Value(x, y, seed, period) + 0.4f * Value(x * 2f, y * 2f, seed + 7, period * 2);
        }
    }
}
